import { GoogleGenAI, Type } from "@google/genai";
import { ResearchMethodology, DifficultyLevel, Feedback, Panelist } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeAbstract = async (text: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze the following research abstract and extract key details for a viva simulation. 
    Abstract: ${text}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          wordCount: { type: Type.INTEGER },
          keyTopics: { 
            type: Type.ARRAY, 
            items: { type: Type.STRING } 
          },
          technicalTermsCount: { type: Type.INTEGER }
        },
        required: ["wordCount", "keyTopics", "technicalTermsCount"]
      }
    }
  });
  return JSON.parse(response.text);
};

export const generateQuestions = async (
  abstract: string, 
  panelist: Panelist, 
  difficulty: DifficultyLevel,
  focusAreas: string[]
) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Act as ${panelist.name}, a ${panelist.role} (${panelist.persona}). 
    Difficulty: ${difficulty}. 
    Focus Areas: ${focusAreas.join(', ')}.
    Based on this research abstract, generate 5 challenging viva questions.
    Abstract: ${abstract}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            category: { type: Type.STRING, description: "One of: Problem, Literature, Methodology, Results, Conclusion, Implementation" }
          },
          required: ["question", "category"]
        }
      }
    }
  });
  return JSON.parse(response.text);
};

export const evaluateResponse = async (
  question: string,
  answer: string,
  abstract: string
): Promise<Feedback> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Evaluate the student's answer to the viva question based on their research abstract.
    Question: ${question}
    Student Answer: ${answer}
    Context Abstract: ${abstract}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.INTEGER },
          semanticRelevance: { type: Type.INTEGER },
          keywordAccuracy: { type: Type.INTEGER },
          confidenceLevel: { type: Type.INTEGER },
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          improvements: { type: Type.ARRAY, items: { type: Type.STRING } },
          betterExample: { type: Type.STRING }
        },
        required: ["score", "semanticRelevance", "keywordAccuracy", "confidenceLevel", "strengths", "improvements", "betterExample"]
      }
    }
  });
  return JSON.parse(response.text);
};

import React, { useState, useEffect } from 'react';
import LoginView from './views/Auth/LoginView';
import RegisterView from './views/Auth/RegisterView';
import VerificationView from './views/Auth/VerificationView';
import DashboardView from './views/Dashboard/DashboardView';
import ProjectSetupView from './views/Project/ProjectSetupView';
import AbstractUploadView from './views/Project/AbstractUploadView';
import SessionConfigView from './views/Session/SessionConfigView';
import PracticeSessionView from './views/Session/PracticeSessionView';
import SessionSummaryView from './views/Session/SessionSummaryView';
import ReadinessDashboardView from './views/Dashboard/ReadinessDashboardView';
import { ProjectProfile, SessionResult } from './types';

enum ViewState {
  LOGIN,
  REGISTER,
  VERIFICATION_PENDING,
  EMAIL_VERIFIED,
  DASHBOARD,
  PROJECT_SETUP,
  ABSTRACT_UPLOAD,
  SESSION_CONFIG,
  PRACTICE_SESSION,
  SESSION_SUMMARY,
  READINESS_DASHBOARD
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LOGIN);
  const [user, setUser] = useState<{ name: string; email: string } | null>(null);
  const [project, setProject] = useState<ProjectProfile | null>(null);
  const [lastSession, setLastSession] = useState<SessionResult | null>(null);

  // Demo account simulation
  const handleLogin = (email: string) => {
    setUser({ name: 'Juan Dela Cruz', email });
    setCurrentView(ViewState.DASHBOARD);
  };

  const handleRegister = (data: any) => {
    setUser({ name: data.fullName, email: data.email });
    setCurrentView(ViewState.VERIFICATION_PENDING);
  };

  const startSession = () => setCurrentView(ViewState.SESSION_CONFIG);
  const finishSetup = (p: ProjectProfile) => {
    setProject(p);
    setCurrentView(ViewState.DASHBOARD);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 overflow-x-hidden">
      {/* Dynamic View Rendering */}
      {currentView === ViewState.LOGIN && (
        <LoginView onLogin={handleLogin} onGoToRegister={() => setCurrentView(ViewState.REGISTER)} />
      )}

      {currentView === ViewState.REGISTER && (
        <RegisterView onRegister={handleRegister} onGoToLogin={() => setCurrentView(ViewState.LOGIN)} />
      )}

      {currentView === ViewState.VERIFICATION_PENDING && (
        <VerificationView 
          status="pending" 
          email={user?.email || ''} 
          onVerify={() => setCurrentView(ViewState.EMAIL_VERIFIED)} 
        />
      )}

      {currentView === ViewState.EMAIL_VERIFIED && (
        <VerificationView 
          status="verified" 
          onGoToLogin={() => setCurrentView(ViewState.LOGIN)} 
        />
      )}

      {currentView === ViewState.DASHBOARD && (
        <DashboardView 
          user={user} 
          project={project}
          onStartProject={() => setCurrentView(ViewState.PROJECT_SETUP)}
          onStartPractice={startSession}
          onViewAnalytics={() => setCurrentView(ViewState.READINESS_DASHBOARD)}
          onLogout={() => { setUser(null); setCurrentView(ViewState.LOGIN); }}
        />
      )}

      {currentView === ViewState.PROJECT_SETUP && (
        <ProjectSetupView 
          onSave={(p) => { setProject(p); setCurrentView(ViewState.ABSTRACT_UPLOAD); }} 
          onCancel={() => setCurrentView(ViewState.DASHBOARD)}
        />
      )}

      {currentView === ViewState.ABSTRACT_UPLOAD && (
        <AbstractUploadView 
          project={project!} 
          onComplete={(p) => finishSetup(p)} 
        />
      )}

      {currentView === ViewState.SESSION_CONFIG && (
        <SessionConfigView 
          onStart={(config) => setCurrentView(ViewState.PRACTICE_SESSION)}
          onBack={() => setCurrentView(ViewState.DASHBOARD)}
        />
      )}

      {currentView === ViewState.PRACTICE_SESSION && (
        <PracticeSessionView 
          project={project!}
          onComplete={(result) => { setLastSession(result); setCurrentView(ViewState.SESSION_SUMMARY); }}
          onExit={() => setCurrentView(ViewState.DASHBOARD)}
        />
      )}

      {currentView === ViewState.SESSION_SUMMARY && (
        <SessionSummaryView 
          result={lastSession!} 
          onGoDashboard={() => setCurrentView(ViewState.DASHBOARD)}
          onViewDetailed={() => setCurrentView(ViewState.READINESS_DASHBOARD)}
        />
      )}

      {currentView === ViewState.READINESS_DASHBOARD && (
        <ReadinessDashboardView 
          onBack={() => setCurrentView(ViewState.DASHBOARD)} 
          onNewSession={startSession}
        />
      )}
    </div>
  );
};

export default App;

