import React, { useState, useEffect } from 'react';
import { Upload, FileText, CheckCircle, Loader2, Info } from 'lucide-react';
import { ProjectProfile } from '../../types';
import { analyzeAbstract } from '../../services/geminiService';

interface Props {
  project: ProjectProfile;
  onComplete: (project: ProjectProfile) => void;
}

const AbstractUploadView: React.FC<Props> = ({ project, onComplete }) => {
  const [step, setStep] = useState<'upload' | 'processing' | 'result'>('upload');
  const [progress, setProgress] = useState(0);
  const [abstractText, setAbstractText] = useState('');
  const [results, setResults] = useState<any>(null);

  const simulateProcessing = async (text: string) => {
    setStep('processing');
    setAbstractText(text);

    // Simulate real-time progress for visual feedback
    for (let i = 0; i <= 100; i += 5) {
      setProgress(i);
      await new Promise(r => setTimeout(r, 100));
    }

    try {
      const analysis = await analyzeAbstract(text);
      setResults(analysis);
      setStep('result');
    } catch (e) {
      console.error("Analysis failed", e);
      // Fallback dummy results for demo if key fails
      setResults({
        wordCount: text.split(' ').length,
        keyTopics: ['Artificial Intelligence', 'Software Engineering', 'Academic Assessment'],
        technicalTermsCount: 15
      });
      setStep('result');
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    // In a real app we'd use a PDF parser, for prototype we use static sample text
    simulateProcessing(`This research project explores the integration of advanced natural language processing models into educational frameworks. Specifically, the IntegrityLens system utilizes transformer-based architectures to simulate viva voce environments, allowing students to engage in rigorous oral defense rehearsals. The methodology follows a quantitative analysis of system performance metrics and user feedback loops to determine efficacy.`);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col p-4 md:p-10">
      <div className="max-w-3xl mx-auto w-full">
        {step === 'upload' && (
          <div className="bg-white rounded-3xl p-10 shadow-sm border border-slate-200 text-center">
            <div className="mb-10">
              <h1 className="text-3xl font-bold text-slate-800 mb-2">Upload Your Abstract</h1>
              <p className="text-slate-500">Project: <span className="font-bold text-slate-800">{project.title}</span></p>
            </div>

            <div 
              className="border-2 border-dashed border-slate-200 rounded-3xl p-16 hover:border-blue-400 hover:bg-blue-50 transition-all cursor-pointer group"
              onClick={() => document.getElementById('file-upload')?.click()}
            >
              <input type="file" id="file-upload" className="hidden" onChange={handleFileUpload} accept=".pdf,.docx,.txt" />
              <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-400 group-hover:bg-blue-100 group-hover:text-blue-600 transition-all">
                <Upload className="w-10 h-10" />
              </div>
              <p className="text-xl font-bold text-slate-800 mb-2">Drag & drop your abstract here</p>
              <p className="text-slate-500 mb-6">or <span className="text-blue-600 font-bold underline">Browse Files</span></p>

              <div className="flex flex-wrap justify-center gap-4 text-xs font-semibold text-slate-400">
                <span className="px-2 py-1 bg-slate-100 rounded">PDF, DOCX, TXT</span>
                <span className="px-2 py-1 bg-slate-100 rounded">MAX 5MB</span>
                <span className="px-2 py-1 bg-slate-100 rounded">500-2000 WORDS</span>
              </div>
            </div>

            <div className="mt-10 flex items-start gap-3 p-4 bg-blue-50 rounded-2xl text-left text-blue-800 text-sm">
              <Info className="w-5 h-5 flex-shrink-0 mt-0.5" />
              <p>A well-structured abstract helps our AI generate better, more contextually relevant practice questions for your simulation.</p>
            </div>
          </div>
        )}

        {step === 'processing' && (
          <div className="bg-white rounded-3xl p-10 shadow-sm border border-slate-200 text-center">
            <Loader2 className="w-12 h-12 text-blue-600 animate-spin mx-auto mb-6" />
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Processing Your Abstract...</h2>
            <p className="text-slate-500 mb-10">Extracting and analyzing key research components</p>

            <div className="space-y-4 text-left mb-10 max-w-md mx-auto">
              <div className="flex items-center gap-3">
                <CheckCircle className="w-5 h-5 text-green-500" />
                <span className="text-slate-700">File uploaded successfully</span>
              </div>
              <div className="flex items-center gap-3">
                {progress > 40 ? <CheckCircle className="w-5 h-5 text-green-500" /> : <Loader2 className="w-5 h-5 text-blue-400 animate-spin" />}
                <span className={progress > 40 ? "text-slate-700" : "text-slate-400"}>Extracting content text</span>
              </div>
              <div className="flex items-center gap-3">
                {progress > 70 ? <CheckCircle className="w-5 h-5 text-green-500" /> : <Loader2 className="w-5 h-5 text-blue-400 animate-spin" />}
                <span className={progress > 70 ? "text-slate-700" : "text-slate-400"}>Identifying research methodology</span>
              </div>
              <div className="flex items-center gap-3">
                {progress > 95 ? <CheckCircle className="w-5 h-5 text-green-500" /> : <Loader2 className="w-5 h-5 text-blue-400 animate-spin" />}
                <span className={progress > 95 ? "text-slate-700" : "text-slate-400"}>Analyzing technical keywords</span>
              </div>
            </div>

            <div className="relative pt-1 max-w-md mx-auto">
              <div className="flex mb-2 items-center justify-between">
                <div>
                  <span className="text-xs font-semibold inline-block py-1 px-2 uppercase rounded-full text-blue-600 bg-blue-200">
                    Analysis Progress
                  </span>
                </div>
                <div className="text-right">
                  <span className="text-xs font-semibold inline-block text-blue-600">
                    {progress}%
                  </span>
                </div>
              </div>
              <div className="overflow-hidden h-2 mb-4 text-xs flex rounded bg-blue-100">
                <div style={{ width: `${progress}%` }} className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-blue-600 transition-all duration-300"></div>
              </div>
              <p className="text-xs text-slate-400 italic">This usually takes 15-30 seconds</p>
            </div>
          </div>
        )}

        {step === 'result' && (
          <div className="bg-white rounded-3xl p-10 shadow-sm border border-slate-200">
            <div className="text-center mb-10">
              <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 text-green-600">
                <CheckCircle className="w-8 h-8" />
              </div>
              <h2 className="text-3xl font-bold text-slate-800">Abstract Analyzed!</h2>
              <p className="text-slate-500">We've extracted the following details from your research.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
              <div className="p-6 bg-slate-50 rounded-2xl">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Word Count</p>
                <p className="text-2xl font-bold text-slate-800">{results.wordCount} words</p>
              </div>
              <div className="p-6 bg-slate-50 rounded-2xl">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Technical Terms</p>
                <p className="text-2xl font-bold text-slate-800">{results.technicalTermsCount} identified</p>
              </div>
              <div className="md:col-span-2 p-6 bg-slate-50 rounded-2xl">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Key Topics Identified</p>
                <div className="flex flex-wrap gap-2">
                  {results.keyTopics.map((topic: string, i: number) => (
                    <span key={i} className="px-4 py-2 bg-white border border-slate-200 rounded-full text-sm font-semibold text-slate-700">
                      {topic}
                    </span>
                  ))}
                </div>
              </div>
            </div>

            <button 
              onClick={() => onComplete({ ...project, abstractText, analysisResults: results })}
              className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-2xl shadow-lg transition-all"
            >
              Finish Setup & Start Practice
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default AbstractUploadView;

import React, { useState } from 'react';
import { Clock, BarChart, Target, UserCheck, MessageSquare, ChevronLeft } from 'lucide-react';
