  const [selectedPanelistId, setSelectedPanelistId] = useState(PANELISTS[1].id);
  const [mode, setMode] = useState('text');

  const toggleFocus = (area: string) => {
    if (focusAreas.includes(area)) {
      setFocusAreas(focusAreas.filter(a => a !== area));
    } else {
      setFocusAreas([...focusAreas, area]);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 md:p-10 flex flex-col items-center">
      <div className="max-w-4xl w-full">
        <header className="mb-10">
          <button onClick={onBack} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors mb-4">
            <ChevronLeft className="w-5 h-5" /> Back to Dashboard
          </button>
          <h1 className="text-3xl font-bold text-slate-800">Configure Practice Session</h1>
          <p className="text-slate-500">Customize your simulation environment for better preparation.</p>
        </header>

        <div className="bg-white rounded-3xl p-8 border border-slate-200 shadow-sm space-y-10">
          {/* Duration */}
          <section>
            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <Clock className="w-4 h-4" /> Session Duration
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              {[15, 30, 45].map((d) => (
                <button 
                  key={d}
                  onClick={() => setDuration(d)}
                  className={`p-4 rounded-2xl border-2 transition-all text-left ${
                    duration === d ? 'border-blue-600 bg-blue-50' : 'border-slate-100 hover:border-slate-300'
                  }`}
