export default SessionConfigView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  X, Mic, Send, Loader2, Sparkles, 
  MessageCircle, Timer, ChevronRight, CheckCircle2,
  AlertCircle
} from 'lucide-react';
import { ProjectProfile, Feedback, SessionResult } from '../../types';
import { PANELISTS } from '../../constants';
import { generateQuestions, evaluateResponse } from '../../services/geminiService';

interface Props {
  project: ProjectProfile;
  onComplete: (result: SessionResult) => void;
  onExit: () => void;
}

const PracticeSessionView: React.FC<Props> = ({ project, onComplete, onExit }) => {
  const [phase, setPhase] = useState<'intro' | 'active' | 'evaluating' | 'feedback'>('intro');
  const [questions, setQuestions] = useState<any[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(1800); // 30 mins
  const [response, setResponse] = useState('');
  const [currentFeedback, setCurrentFeedback] = useState<Feedback | null>(null);
  const [sessionScores, setSessionScores] = useState<number[]>([]);
  const panelist = PANELISTS[1]; // Using Prof. Santos by default for demo

  useEffect(() => {
    const fetchQuestions = async () => {
      try {
        const q = await generateQuestions(project.abstractText || '', panelist, project.methodology as any, ['Methodology']);
        setQuestions(q);
      } catch (e) {
        // Fallback for prototype
        setQuestions([
          { question: `Can you explain why you chose a ${project.methodology} research methodology over other approaches for this project?`, category: 'Methodology' },
          { question: "How does your system handle potential data noise during initial collection phases?", category: 'Implementation' },
          { question: "What are the core limitations of the technology stack you selected?", category: 'Technical' }
        ]);
      }
    };
    fetchQuestions();
  }, []);

  useEffect(() => {
    let timer: any;
    if (phase === 'active' || phase === 'feedback') {
      timer = setInterval(() => {
        setTimeLeft((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [phase]);

  const handleSubmit = async () => {
    if (!response.trim()) return;
    setPhase('evaluating');

    try {
      const evalRes = await evaluateResponse(questions[currentIndex].question, response, project.abstractText || '');
      setCurrentFeedback(evalRes);
      setSessionScores([...sessionScores, evalRes.score]);
      setPhase('feedback');
    } catch (e) {
      // Fallback
      setCurrentFeedback({
        score: 75,
        semanticRelevance: 80,
        keywordAccuracy: 70,
        confidenceLevel: 75,
        strengths: ["Clear logic", "Good tech mention"],
        improvements: ["Be more specific about data"],
        betterExample: "A more robust response would include..."
      });
      setSessionScores([...sessionScores, 75]);
      setPhase('feedback');
    }
  };

  const nextQuestion = () => {
    if (currentIndex + 1 < questions.length) {
      setCurrentIndex(currentIndex + 1);
      setResponse('');
      setPhase('active');
    } else {
      const avg = sessionScores.length > 0 ? sessionScores.reduce((a,b) => a+b, 0) / sessionScores.length : 0;
      onComplete({
        id: Math.random().toString(),
        date: new Date().toLocaleDateString(),
        overallScore: Math.round(avg),
        duration: 30 - Math.floor(timeLeft / 60),
        questionsAnswered: questions.length,
        categoryScores: { Methodology: 75, Implementation: 80 }
      });
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  return (
    <div className="min-h-screen bg-slate-900 text-white flex flex-col">
      {/* Top Bar */}
      <header className="px-6 py-4 border-b border-white/10 flex items-center justify-between bg-slate-900 sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center font-bold">IL</div>
          <div>
            <p className="font-bold text-sm leading-none mb-1">Practice Session</p>
            <p className="text-xs text-slate-400">IntegrityLens AI Simulator</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden sm:flex items-center gap-2 px-4 py-2 bg-white/5 rounded-full text-slate-300 font-mono">
            <Timer className="w-4 h-4 text-blue-400" />
            {formatTime(timeLeft)}
          </div>
          <button onClick={onExit} className="px-4 py-2 hover:bg-white/5 rounded-xl transition-colors text-sm font-bold flex items-center gap-2">
            <X className="w-4 h-4" /> Exit Session
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col items-center justify-center p-4 sm:p-10">
        <div className="max-w-4xl w-full">
          {phase === 'intro' && (
            <div className="bg-white/5 border border-white/10 p-10 rounded-3xl backdrop-blur-sm text-center">
              <div className="w-20 h-20 bg-blue-600/20 text-blue-400 rounded-full flex items-center justify-center mx-auto mb-6">
                <MessageCircle className="w-10 h-10" />
              </div>
              <h2 className="text-2xl font-bold mb-4">Ready to Begin?</h2>
              <div className="bg-white/5 p-6 rounded-2xl text-left mb-8 space-y-4">
                <p className="text-slate-300">
                  <span className="font-bold text-white">Panelist:</span> {panelist.name} ({panelist.role})
                </p>
                <p className="text-slate-300">
                  Good afternoon. I'm Professor Santos. This session will focus on your research methodology with intermediate-level questions.
                </p>
                <p className="text-slate-300 italic">
                  Take your time and explain your answers clearly. Let's begin.
                </p>
              </div>
              <button 
                onClick={() => setPhase('active')}
                className="px-12 py-4 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-2xl transition-all shadow-lg shadow-blue-900/20"
              >
                Start Simulation
              </button>
            </div>
          )}

          {phase === 'active' && questions.length > 0 && (
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-bold text-blue-400 uppercase tracking-widest">Question {currentIndex + 1} of {questions.length}</span>
                <span className="text-xs text-slate-500 uppercase font-bold tracking-widest">Category: {questions[currentIndex].category}</span>
              </div>

              <div className="bg-white/5 border border-white/10 p-8 rounded-3xl">
                <p className="text-2xl font-medium text-slate-100 leading-relaxed">
                  "{questions[currentIndex].question}"
                </p>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest">Your Response</h3>
                  <span className="text-xs text-slate-500">{response.length}/1000 characters</span>
                </div>
                <div className="relative">
                  <textarea 
                    autoFocus
                    className="w-full min-h-[200px] bg-white/5 border border-white/10 rounded-3xl p-6 focus:ring-2 focus:ring-blue-500 outline-none text-slate-200 placeholder:text-slate-600 resize-none transition-all"
                    placeholder="Provide your defense explanation here..."
                    value={response}
                    onChange={(e) => setResponse(e.target.value)}
                  />
                  <div className="absolute right-4 bottom-4 flex gap-2">
                    <button className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-slate-400">
                      <Mic className="w-5 h-5" />
                    </button>
                  </div>
                </div>

                <div className="flex gap-4">
                  <button className="flex-1 py-4 bg-white/5 hover:bg-white/10 text-slate-400 font-bold rounded-2xl transition-all">
                    Skip Question
                  </button>
                  <button 
                    disabled={!response}
                    onClick={handleSubmit}
                    className="flex-[2] py-4 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-2xl transition-all flex items-center justify-center gap-2 shadow-lg shadow-blue-900/20"
                  >
                    Submit Answer <Send className="w-5 h-5" />
                  </button>
                </div>
              </div>
            </div>
          )}

          {phase === 'evaluating' && (
            <div className="text-center py-20">
              <Loader2 className="w-16 h-16 text-blue-500 animate-spin mx-auto mb-8" />
              <h2 className="text-3xl font-bold mb-4">Evaluating your response...</h2>
              <div className="max-w-md mx-auto space-y-4 text-left">
                <div className="flex items-center gap-3 p-3 bg-white/5 rounded-2xl">
                  <CheckCircle2 className="w-5 h-5 text-green-500" />
                  <span className="text-slate-300">Semantic relevance to question</span>
                </div>
                <div className="flex items-center gap-3 p-3 bg-white/5 rounded-2xl animate-pulse">
                  <Sparkles className="w-5 h-5 text-blue-400" />
                  <span className="text-slate-300">Keyword accuracy and coverage...</span>
                </div>
                <div className="flex items-center gap-3 p-3 bg-white/5 rounded-2xl opacity-40">
                  <Loader2 className="w-5 h-5 text-slate-400 animate-spin" />
                  <span className="text-slate-300">Confidence and clarity indicators</span>
                </div>
              </div>
            </div>
          )}

          {phase === 'feedback' && currentFeedback && (
            <div className="space-y-8 animate-in zoom-in-95 duration-500">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div>
                  <span className="text-xs font-bold text-blue-400 uppercase tracking-widest mb-1 block">Evaluation Summary</span>
                  <h2 className="text-2xl font-bold">Prof. Santos' Feedback</h2>
                </div>
                <div className="bg-white/10 px-6 py-4 rounded-3xl flex items-center gap-4">
                  <div className="text-right">
                    <p className="text-xs text-slate-400 font-bold uppercase">Your Score</p>
                    <p className="text-3xl font-bold text-blue-400">{currentFeedback.score}/100</p>
                  </div>
                  <div className="w-12 h-12 bg-blue-500 rounded-2xl flex items-center justify-center">
                    <CheckCircle2 className="w-8 h-8 text-white" />
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="md:col-span-2 space-y-6">
                  <div className="bg-white/5 border border-white/10 rounded-3xl p-8">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                      <div className="space-y-4">
                        <h4 className="text-green-400 font-bold flex items-center gap-2">
                          <CheckCircle2 className="w-5 h-5" /> Strengths
                        </h4>
                        <ul className="space-y-2">
                          {currentFeedback.strengths.map((s, i) => (
                            <li key={i} className="text-slate-300 text-sm flex gap-2">
                              <span className="text-green-500">•</span> {s}
                            </li>
                          ))}
                        </ul>
                      </div>
                      <div className="space-y-4">
                        <h4 className="text-amber-400 font-bold flex items-center gap-2">
                          <AlertCircle className="w-5 h-5" /> Improvements
                        </h4>
                        <ul className="space-y-2">
                          {currentFeedback.improvements.map((s, i) => (
                            <li key={i} className="text-slate-300 text-sm flex gap-2">
                              <span className="text-amber-500">•</span> {s}
                            </li>
                          ))}
                        </ul>
                      </div>
                    </div>
                  </div>

                  <div className="bg-blue-600/10 border border-blue-500/20 rounded-3xl p-8">
                    <h4 className="text-blue-400 font-bold mb-3">💡 Pro Tip</h4>
                    <p className="text-slate-300 text-sm italic leading-relaxed">
                      "{currentFeedback.betterExample}"
                    </p>
                  </div>
                </div>

                <div className="space-y-6">
                  <div className="bg-white/5 border border-white/10 rounded-3xl p-6 space-y-6">
                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest">Metrics</h4>
                    <div>
                      <div className="flex justify-between text-xs mb-1">
                        <span className="text-slate-300">Semantic Relevance</span>
                        <span className="text-blue-400">{currentFeedback.semanticRelevance}%</span>
                      </div>
                      <div className="h-2 bg-white/10 rounded-full overflow-hidden">
                        <div className="h-full bg-blue-500" style={{ width: `${currentFeedback.semanticRelevance}%` }} />
                      </div>
                    </div>
                    <div>
                      <div className="flex justify-between text-xs mb-1">
                        <span className="text-slate-300">Keyword Accuracy</span>
                        <span className="text-blue-400">{currentFeedback.keywordAccuracy}%</span>
                      </div>
                      <div className="h-2 bg-white/10 rounded-full overflow-hidden">
                        <div className="h-full bg-blue-500" style={{ width: `${currentFeedback.keywordAccuracy}%` }} />
                      </div>
                    </div>
                    <div>
                      <div className="flex justify-between text-xs mb-1">
                        <span className="text-slate-300">Confidence Level</span>
                        <span className="text-blue-400">{currentFeedback.confidenceLevel}%</span>
                      </div>
                      <div className="h-2 bg-white/10 rounded-full overflow-hidden">
                        <div className="h-full bg-blue-500" style={{ width: `${currentFeedback.confidenceLevel}%` }} />
                      </div>
                    </div>
                  </div>

                  <button 
                    onClick={nextQuestion}
                    className="w-full py-6 bg-white text-slate-900 font-bold rounded-3xl hover:bg-slate-100 transition-all flex items-center justify-center gap-2 shadow-lg"
                  >
                    Next Question <ChevronRight className="w-5 h-5" />
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

