import { GoogleGenAI, Type } from "@google/genai";
import { ResearchMethodology, DifficultyLevel, Feedback, Panelist } from "../types";

// Always use new GoogleGenAI({apiKey: process.env.API_KEY})
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeAbstract = async (text: string) => {
  // Use gemini-3-flash-preview for basic text tasks like extraction
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze the following research abstract and extract key details for a viva simulation. 
    Abstract: ${text}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          wordCount: { type: Type.INTEGER },
          keyTopics: { 
            type: Type.ARRAY, 
            items: { type: Type.STRING } 
          },
          technicalTermsCount: { type: Type.INTEGER }
        },
        required: ["wordCount", "keyTopics", "technicalTermsCount"]
      }
    }
  });
  // Use response.text property to extract content directly
  return JSON.parse(response.text || '{}');
};

export const generateQuestions = async (
  abstract: string, 
  panelist: Panelist, 
  difficulty: DifficultyLevel,
  focusAreas: string[]
) => {
  // Use gemini-3-pro-preview for complex creative/reasoning tasks like question generation
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Act as ${panelist.name}, a ${panelist.role} (${panelist.persona}). 
    Difficulty: ${difficulty}. 
    Focus Areas: ${focusAreas.join(', ')}.
    Based on this research abstract, generate 5 challenging viva questions.
    Abstract: ${abstract}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            category: { type: Type.STRING, description: "One of: Problem, Literature, Methodology, Results, Conclusion, Implementation" }
          },
          required: ["question", "category"]
        }
      }
    }
  });
  // Use response.text property to extract content directly
  return JSON.parse(response.text || '[]');
};

export const evaluateResponse = async (
  question: string,
  answer: string,
  abstract: string
): Promise<Feedback> => {
  // Use gemini-3-pro-preview for advanced reasoning when evaluating student answers
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Evaluate the student's answer to the viva question based on their research abstract.
    Question: ${question}
    Student Answer: ${answer}
    Context Abstract: ${abstract}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.INTEGER },
          semanticRelevance: { type: Type.INTEGER },
          keywordAccuracy: { type: Type.INTEGER },
          confidenceLevel: { type: Type.INTEGER },
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          improvements: { type: Type.ARRAY, items: { type: Type.STRING } },
          betterExample: { type: Type.STRING }
        },
        required: ["score", "semanticRelevance", "keywordAccuracy", "confidenceLevel", "strengths", "improvements", "betterExample"]
      }
    }
  });
  // Use response.text property to extract content directly
  return JSON.parse(response.text || '{}');
};

import React, { useState } from 'react';
import LandingView from './views/Landing/LandingView';
import LoginView from './views/Auth/LoginView';
import RegisterView from './views/Auth/RegisterView';
import VerificationView from './views/Auth/VerificationView';
import DashboardView from './views/Dashboard/DashboardView';
import FacultyDashboardView from './views/Dashboard/FacultyDashboardView';
import AdminDashboardView from './views/Dashboard/AdminDashboardView';
import ProjectSetupView from './views/Project/ProjectSetupView';
import AbstractUploadView from './views/Project/AbstractUploadView';
import SessionConfigView from './views/Session/SessionConfigView';
import PracticeSessionView from './views/Session/PracticeSessionView';
import SessionSummaryView from './views/Session/SessionSummaryView';
import ReadinessDashboardView from './views/Dashboard/ReadinessDashboardView';
import { ProjectProfile, SessionResult, User, UserRole } from './types';

enum ViewState {
  LANDING,
  LOGIN,
  REGISTER,
  VERIFICATION_PENDING,
  EMAIL_VERIFIED,
  STUDENT_DASHBOARD,
  FACULTY_DASHBOARD,
  ADMIN_DASHBOARD,
  PROJECT_SETUP,
  ABSTRACT_UPLOAD,
  SESSION_CONFIG,
  PRACTICE_SESSION,
  SESSION_SUMMARY,
  READINESS_DASHBOARD
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LANDING);
  const [user, setUser] = useState<User | null>(null);
  const [project, setProject] = useState<ProjectProfile | null>(null);
  const [lastSession, setLastSession] = useState<SessionResult | null>(null);

  const handleLogin = (email: string, role: UserRole) => {
    const demoUser: User = { 
      name: role === UserRole.STUDENT ? 'Juan Dela Cruz' : role === UserRole.FACULTY ? 'Dr. Sarah Santos' : 'System Admin', 
      email: email, 
      role: role,
      program: 'BSIT',
      yearLevel: '4th Year'
    };
    setUser(demoUser);

    if (role === UserRole.STUDENT) setCurrentView(ViewState.STUDENT_DASHBOARD);
    else if (role === UserRole.FACULTY) setCurrentView(ViewState.FACULTY_DASHBOARD);
    else setCurrentView(ViewState.ADMIN_DASHBOARD);
  };

  const handleRegister = (data: any) => {
    setUser({ name: data.fullName, email: data.email, role: UserRole.STUDENT });
    setCurrentView(ViewState.VERIFICATION_PENDING);
  };

  const logout = () => {
    setUser(null);
    setCurrentView(ViewState.LANDING);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 overflow-x-hidden">
      {currentView === ViewState.LANDING && (
        <LandingView 
          onGetStarted={() => setCurrentView(ViewState.REGISTER)} 
          onLogin={() => setCurrentView(ViewState.LOGIN)} 
        />
      )}

      {currentView === ViewState.LOGIN && (
        <LoginView onLogin={handleLogin} onGoToRegister={() => setCurrentView(ViewState.REGISTER)} />
      )}

      {currentView === ViewState.REGISTER && (
        <RegisterView onRegister={handleRegister} onGoToLogin={() => setCurrentView(ViewState.LOGIN)} />
      )}

      {currentView === ViewState.VERIFICATION_PENDING && (
        <VerificationView 
          status="pending" 
          email={user?.email || ''} 
          onVerify={() => setCurrentView(ViewState.EMAIL_VERIFIED)} 
        />
      )}

      {currentView === ViewState.EMAIL_VERIFIED && (
        <VerificationView 
          status="verified" 
          onGoToLogin={() => setCurrentView(ViewState.LOGIN)} 
        />
      )}

      {currentView === ViewState.STUDENT_DASHBOARD && (
        <DashboardView 
          user={user} 
          project={project}
          onStartProject={() => setCurrentView(ViewState.PROJECT_SETUP)}
          onStartPractice={() => setCurrentView(ViewState.SESSION_CONFIG)}
          onViewAnalytics={() => setCurrentView(ViewState.READINESS_DASHBOARD)}
          onLogout={logout}
        />
      )}

      {currentView === ViewState.FACULTY_DASHBOARD && (
        <FacultyDashboardView user={user!} onLogout={logout} />
      )}

      {currentView === ViewState.ADMIN_DASHBOARD && (
        <AdminDashboardView user={user!} onLogout={logout} />
      )}

      {currentView === ViewState.PROJECT_SETUP && (
        <ProjectSetupView 
          onSave={(p) => { setProject(p); setCurrentView(ViewState.ABSTRACT_UPLOAD); }} 
          onCancel={() => setCurrentView(ViewState.STUDENT_DASHBOARD)}
        />
      )}

      {currentView === ViewState.ABSTRACT_UPLOAD && (
        <AbstractUploadView 
          project={project!} 
          onComplete={(p) => { setProject(p); setCurrentView(ViewState.STUDENT_DASHBOARD); }} 
        />
      )}

      {currentView === ViewState.SESSION_CONFIG && (
        <SessionConfigView 
          onStart={() => setCurrentView(ViewState.PRACTICE_SESSION)}
          onBack={() => setCurrentView(ViewState.STUDENT_DASHBOARD)}
        />
      )}

      {currentView === ViewState.PRACTICE_SESSION && (
        <PracticeSessionView 
          project={project!}
          onComplete={(result) => { setLastSession(result); setCurrentView(ViewState.SESSION_SUMMARY); }}
          onExit={() => setCurrentView(ViewState.STUDENT_DASHBOARD)}
        />
      )}

      {currentView === ViewState.SESSION_SUMMARY && (
        <SessionSummaryView 
          result={lastSession!} 
          onGoDashboard={() => setCurrentView(ViewState.STUDENT_DASHBOARD)}
          onViewDetailed={() => setCurrentView(ViewState.READINESS_DASHBOARD)}
        />
      )}

      {currentView === ViewState.READINESS_DASHBOARD && (
        <ReadinessDashboardView 
          onBack={() => setCurrentView(ViewState.STUDENT_DASHBOARD)} 
          onNewSession={() => setCurrentView(ViewState.SESSION_CONFIG)}
        />
      )}
    </div>
  );
};

export default App;

export enum UserRole {
  STUDENT = 'STUDENT',
  FACULTY = 'FACULTY',
  ADMIN = 'ADMIN'
}

export interface User {
  name: string;
  email: string;
  role: UserRole;
  program?: string;
  yearLevel?: string;
}

export enum ResearchMethodology {
  QUANTITATIVE = 'Quantitative',
  QUALITATIVE = 'Qualitative',
  MIXED_METHODS = 'Mixed Methods',
  EXPERIMENTAL = 'Experimental'
}

export enum DifficultyLevel {
  BEGINNER = 'Beginner',
  INTERMEDIATE = 'Intermediate',
  ADVANCED = 'Advanced'
}

export interface Panelist {
  id: string;
  name: string;
  role: string;
  specialization: string;
  persona: string;
}

export interface ProjectProfile {
  title: string;
  methodology: ResearchMethodology;
  techStack: string;
  defenseDate: string;
  adviser: string;
  description: string;
  abstractText?: string;
  analysisResults?: AnalysisResult;
}

export interface AnalysisResult {
  wordCount: number;
  keyTopics: string[];
  technicalTermsCount: number;
}

export interface Feedback {
  score: number;
  semanticRelevance: number;
  keywordAccuracy: number;
  confidenceLevel: number;
  strengths: string[];
  improvements: string[];
  betterExample: string;
}

export interface QuestionAnswer {
  question: string;
  answer: string;
  feedback: Feedback;
  category: string;
}

export interface SessionResult {
  id: string;
  date: string;
  overallScore: number;
  duration: number;
  questionsAnswered: number;
  categoryScores: Record<string, number>;
  history: QuestionAnswer[];
}

import React, { useState, useEffect } from 'react';
import { 
  X, Mic, Send, Loader2, Sparkles, 
  MessageCircle, Timer, ChevronRight, CheckCircle2,
  AlertCircle
} from 'lucide-react';
import { ProjectProfile, Feedback, SessionResult, QuestionAnswer } from '../../types';
import { PANELISTS } from '../../constants';
import { generateQuestions, evaluateResponse } from '../../services/geminiService';

interface Props {
  project: ProjectProfile;
  onComplete: (result: SessionResult) => void;
  onExit: () => void;
}

const PracticeSessionView: React.FC<Props> = ({ project, onComplete, onExit }) => {
  const [phase, setPhase] = useState<'intro' | 'active' | 'evaluating' | 'feedback'>('intro');
  const [questions, setQuestions] = useState<any[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(1800); // 30 mins
  const [response, setResponse] = useState('');
  const [currentFeedback, setCurrentFeedback] = useState<Feedback | null>(null);
  const [history, setHistory] = useState<QuestionAnswer[]>([]);
  const [sessionScores, setSessionScores] = useState<number[]>([]);
  const panelist = PANELISTS[1]; // Using Prof. Santos by default for demo

  useEffect(() => {
    const fetchQuestions = async () => {
      try {
        const q = await generateQuestions(project.abstractText || '', panelist, project.methodology as any, ['Methodology']);
        setQuestions(q);
      } catch (e) {
        setQuestions([
          { question: `Can you explain why you chose a ${project.methodology} research methodology over other approaches for this project?`, category: 'Methodology' },
          { question: "How does your system handle potential data noise during initial collection phases?", category: 'Implementation' },
          { question: "What are the core limitations of the technology stack you selected?", category: 'Technical' }
        ]);
      }
    };
    fetchQuestions();
  }, [project.abstractText, project.methodology]);

  useEffect(() => {
    let timer: any;
    if (phase === 'active' || phase === 'feedback') {
      timer = setInterval(() => {
        setTimeLeft((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [phase]);

  const handleSubmit = async () => {
    if (!response.trim()) return;
    const currentQuestion = questions[currentIndex];
    setPhase('evaluating');

    try {
      const evalRes = await evaluateResponse(currentQuestion.question, response, project.abstractText || '');
      setCurrentFeedback(evalRes);
      setSessionScores([...sessionScores, evalRes.score]);
      setHistory([
        ...history, 
        { 
          question: currentQuestion.question, 
          answer: response, 
          feedback: evalRes,
          category: currentQuestion.category 
        }
      ]);
      setPhase('feedback');
    } catch (e) {
      const fallbackFeedback: Feedback = {
        score: 75,
        semanticRelevance: 80,
        keywordAccuracy: 70,
        confidenceLevel: 75,
        strengths: ["Clear logic", "Good tech mention"],
        improvements: ["Be more specific about data"],
        betterExample: "A more robust response would include specific metrics from your methodology chapter."
      };
      setCurrentFeedback(fallbackFeedback);
      setSessionScores([...sessionScores, 75]);
      setHistory([
        ...history, 
        { 
          question: currentQuestion.question, 
          answer: response, 
          feedback: fallbackFeedback,
          category: currentQuestion.category 
        }
      ]);
      setPhase('feedback');
    }
  };

  const nextQuestion = () => {
    if (currentIndex + 1 < questions.length) {
      setCurrentIndex(currentIndex + 1);
      setResponse('');
      setPhase('active');
    } else {
      const avg = sessionScores.length > 0 ? sessionScores.reduce((a,b) => a+b, 0) / sessionScores.length : 0;
      onComplete({
        id: Math.random().toString(36).substr(2, 9),
        date: new Date().toLocaleDateString(),
        overallScore: Math.round(avg),
        duration: 30 - Math.floor(timeLeft / 60),
        questionsAnswered: history.length,
        categoryScores: { Methodology: 75, Implementation: 80 },
        history: history
      });
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  return (
    <div className="min-h-screen bg-slate-900 text-white flex flex-col">
      <header className="px-6 py-4 border-b border-white/10 flex items-center justify-between bg-slate-900 sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center font-bold">IL</div>
          <div>
            <p className="font-bold text-sm leading-none mb-1">Practice Session</p>
            <p className="text-xs text-slate-400">IntegrityLens AI Simulator</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden sm:flex items-center gap-2 px-4 py-2 bg-white/5 rounded-full text-slate-300 font-mono">
            <Timer className="w-4 h-4 text-blue-400" />
            {formatTime(timeLeft)}
          </div>
          <button onClick={onExit} className="px-4 py-2 hover:bg-white/5 rounded-xl transition-colors text-sm font-bold flex items-center gap-2">
            <X className="w-4 h-4" /> Exit Session
          </button>
        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-4 sm:p-10">
        <div className="max-w-4xl w-full">
          {phase === 'intro' && (
            <div className="bg-white/5 border border-white/10 p-10 rounded-3xl backdrop-blur-sm text-center">
              <div className="w-20 h-20 bg-blue-600/20 text-blue-400 rounded-full flex items-center justify-center mx-auto mb-6">
                <MessageCircle className="w-10 h-10" />
              </div>
              <h2 className="text-2xl font-bold mb-4 uppercase tracking-tighter italic">Ready to Begin?</h2>
              <div className="bg-white/5 p-6 rounded-2xl text-left mb-8 space-y-4">
                <p className="text-slate-300">
                  <span className="font-bold text-white uppercase tracking-widest text-[10px]">Panelist:</span> {panelist.name} ({panelist.role})
                </p>
                <p className="text-slate-300 leading-relaxed font-medium">
                  Good afternoon. I'm Professor Santos, and I'll be conducting your oral defense simulation today. This session will focus on your research methodology with intermediate-level questions.
                </p>
                <p className="text-blue-400 italic font-bold">
                  Take your time and explain your answers clearly. Let's begin.
                </p>
              </div>
              <button 
                onClick={() => setPhase('active')}
                className="px-12 py-4 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-2xl transition-all shadow-xl shadow-blue-900/40 uppercase tracking-widest text-sm"
              >
                Start Simulation
              </button>
            </div>
          )}

          {phase === 'active' && questions.length > 0 && (
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-blue-400 uppercase tracking-[0.2em]">Question {currentIndex + 1} of {questions.length}</span>
                <span className="text-[10px] text-slate-500 uppercase font-black tracking-[0.2em]">Track: {questions[currentIndex].category}</span>
              </div>

              <div className="bg-white/5 border border-white/10 p-10 rounded-[40px] shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-5"><MessageCircle className="w-20 h-20" /></div>
                <p className="text-2xl font-bold text-slate-100 leading-relaxed italic">
                  "{questions[currentIndex].question}"
                </p>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Your Defense Response</h3>
                  <span className="text-[10px] font-bold text-slate-600">{response.length}/1000 CHARS</span>
                </div>
                <div className="relative">
                  <textarea 
                    autoFocus
                    className="w-full min-h-[250px] bg-slate-800/50 border border-white/5 rounded-[32px] p-8 focus:ring-2 focus:ring-blue-500 outline-none text-slate-200 placeholder:text-slate-600 resize-none transition-all font-medium leading-relaxed"
                    placeholder="Type your explanation clearly..."
                    value={response}
                    onChange={(e) => setResponse(e.target.value)}
                  />
                  <div className="absolute right-6 bottom-6 flex gap-2">
                    <button className="p-4 bg-blue-500/10 text-blue-400 hover:bg-blue-500/20 rounded-2xl transition-all shadow-sm">
                      <Mic className="w-5 h-5" />
                    </button>
                  </div>
                </div>

                <div className="flex gap-4">
                  <button className="px-8 py-5 bg-white/5 hover:bg-white/10 text-slate-500 font-black rounded-2xl transition-all uppercase tracking-widest text-xs">
                    Skip Question
                  </button>
                  <button 
                    disabled={!response}
                    onClick={handleSubmit}
                    className="flex-grow py-5 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 disabled:cursor-not-allowed text-white font-black rounded-2xl transition-all flex items-center justify-center gap-2 shadow-xl shadow-blue-900/40 uppercase tracking-widest text-xs"
                  >
                    Submit Answer <Send className="w-4 h-4" />
                  </button>
                </div>
              </div>
            </div>
          )}

          {phase === 'evaluating' && (
            <div className="text-center py-20 animate-in fade-in duration-700">
              <div className="relative w-24 h-24 mx-auto mb-10">
