import React, { useState } from 'react';
import { Clock, BarChart, Target, UserCheck, MessageSquare, ChevronLeft, CheckCircle2 } from 'lucide-react';
import { DifficultyLevel } from '../../types';
import { PANELISTS, CATEGORIES } from '../../constants';

interface Props {
  onStart: (config: any) => void;
  onBack: () => void;
}

const SessionConfigView: React.FC<Props> = ({ onStart, onBack }) => {
  const [duration, setDuration] = useState(30);
  const [difficulty, setDifficulty] = useState<DifficultyLevel>(DifficultyLevel.INTERMEDIATE);
  const [focusAreas, setFocusAreas] = useState<string[]>(['Problem Statement', 'Methodology']);
  const [selectedPanelistIds, setSelectedPanelistIds] = useState<string[]>([PANELISTS[1].id]);
  const [mode, setMode] = useState('text');

  const toggleFocus = (area: string) => {
    if (focusAreas.includes(area)) {
      setFocusAreas(focusAreas.filter(a => a !== area));
    } else {
      setFocusAreas([...focusAreas, area]);
    }
  };

  const togglePanelist = (id: string) => {
    if (selectedPanelistIds.includes(id)) {
      if (selectedPanelistIds.length > 1) {
        setSelectedPanelistIds(selectedPanelistIds.filter(pid => pid !== id));
      }
    } else {
      setSelectedPanelistIds([...selectedPanelistIds, id]);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 md:p-10 flex flex-col items-center">
      <div className="max-w-4xl w-full">
        <header className="mb-10">
          <button onClick={onBack} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors mb-4 group font-bold">
            <ChevronLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform" /> Back to Dashboard
          </button>
          <h1 className="text-3xl font-black text-slate-800 tracking-tighter uppercase italic">Configure Practice Session</h1>
          <p className="text-slate-500">Customize your virtual panel for a tailored defense simulation.</p>
