          <section>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
              <Clock className="w-4 h-4 text-blue-500" /> Session Duration
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              {[15, 30, 45].map((d) => (
                <button 
                  key={d}
                  onClick={() => setDuration(d)}
                  className={`p-6 rounded-3xl border-2 transition-all text-left relative overflow-hidden group ${
                    duration === d ? 'border-blue-600 bg-blue-50/50' : 'border-slate-100 hover:border-slate-200 bg-slate-50/30'
                  }`}
                >
                  <p className={`font-black uppercase tracking-tighter text-lg ${duration === d ? 'text-blue-700' : 'text-slate-800'}`}>{d} minutes</p>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{d === 15 ? 'Quick Practice' : d === 30 ? 'Recommended' : 'Full Simulation'}</p>
                  {duration === d && <CheckCircle2 className="absolute top-4 right-4 w-5 h-5 text-blue-600" />}
                </button>
              ))}
            </div>
          </section>

          {/* Difficulty */}
          <section>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
              <BarChart className="w-4 h-4 text-indigo-500" /> Difficulty Level
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              {Object.values(DifficultyLevel).map((lv) => (
                <button 
                  key={lv}
                  onClick={() => setDifficulty(lv)}
                  className={`p-5 rounded-2xl border-2 transition-all font-black uppercase tracking-widest text-xs ${
                    difficulty === lv ? 'border-indigo-600 bg-indigo-50 text-indigo-700 shadow-sm' : 'border-slate-100 hover:border-slate-200 text-slate-400 bg-slate-50/30'
                  }`}
                >
                  {lv}
                </button>
              ))}
            </div>
          </section>

          {/* Virtual Panelist - MULTI SELECT */}
          <section>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
