            </h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {PANELISTS.map((p) => {
                const isSelected = selectedPanelistIds.includes(p.id);
                return (
                  <button 
                    key={p.id}
                    onClick={() => togglePanelist(p.id)}
                    className={`p-6 rounded-3xl border-2 transition-all text-center flex flex-col items-center relative group ${
                      isSelected ? 'border-emerald-500 bg-emerald-50/30 shadow-sm' : 'border-slate-100 hover:border-slate-200 bg-slate-50/30'
