                  >
                    <div className={`w-16 h-16 rounded-[24px] mb-4 flex items-center justify-center font-black text-xl text-white shadow-lg transition-transform group-hover:scale-105 ${
                      isSelected ? 'bg-emerald-500' : 'bg-slate-300'
