                      {p.name.split(' ')[1][0]}
                    </div>
                    <p className={`text-xs font-black uppercase tracking-tighter mb-1 ${isSelected ? 'text-emerald-700' : 'text-slate-800'}`}>{p.name}</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest leading-none">{p.role.split(' ')[0]}</p>
