          {/* Mode */}
          <section>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
              <MessageSquare className="w-4 h-4 text-purple-500" /> Interaction Mode
            </h3>
            <div className="flex bg-slate-100 p-1.5 rounded-2xl w-full sm:w-max">
              {['text', 'voice', 'hybrid'].map((m) => (
                <button 
                  key={m}
                  onClick={() => setMode(m)}
                  className={`flex-grow sm:flex-initial px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                    mode === m ? 'bg-white text-slate-900 shadow-md' : 'text-slate-500 hover:text-slate-800'
                  }`}
                >
                  {m}
                </button>
              ))}
            </div>
          </section>

          <div className="pt-8">
            <button 
              onClick={() => onStart({ duration, difficulty, focusAreas, selectedPanelistIds, mode })}
              className="w-full py-6 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-3xl shadow-2xl shadow-blue-200 transition-all uppercase tracking-[0.2em] text-sm"
            >
              Start Session Simulation
