import React, { useState, useEffect } from 'react';
import { 
  X, Mic, Send, Loader2, Sparkles, 
  MessageCircle, Timer, ChevronRight, CheckCircle2,
  AlertCircle, UserCircle
} from 'lucide-react';
import { ProjectProfile, Feedback, SessionResult, QuestionAnswer, Panelist } from '../../types';
import { PANELISTS } from '../../constants';
import { generateQuestions, evaluateResponse } from '../../services/geminiService';

interface Props {
  project: ProjectProfile;
  config?: any;
  onComplete: (result: SessionResult) => void;
  onExit: () => void;
}

const PracticeSessionView: React.FC<Props> = ({ project, config, onComplete, onExit }) => {
  const [phase, setPhase] = useState<'intro' | 'active' | 'evaluating' | 'feedback'>('intro');
  const [questions, setQuestions] = useState<any[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState((config?.duration || 30) * 60);
  const [response, setResponse] = useState('');
  const [currentFeedback, setCurrentFeedback] = useState<Feedback | null>(null);
  const [history, setHistory] = useState<QuestionAnswer[]>([]);
  const [sessionScores, setSessionScores] = useState<number[]>([]);

  // Resolve panelist objects from IDs
  const selectedPanelists = PANELISTS.filter(p => config?.selectedPanelistIds?.includes(p.id)) || [PANELISTS[1]];

  useEffect(() => {
    const fetchQuestions = async () => {
      try {
        // We use the first panelist to drive the question generation logic for now
        const q = await generateQuestions(
          project.abstractText || '', 
          selectedPanelists[0], 
          config?.difficulty || 'Intermediate', 
          config?.focusAreas || ['Methodology']
        );

        // Randomly assign a panelist from the selected list to each question
        const assignedQuestions = q.map((item: any) => ({
          ...item,
          panelist: selectedPanelists[Math.floor(Math.random() * selectedPanelists.length)]
        }));

        setQuestions(assignedQuestions);
      } catch (e) {
        const fallback = [
          { question: `Can you explain why you chose a ${project.methodology} research methodology over other approaches for this project?`, category: 'Methodology' },
          { question: "How does your system handle potential data noise during initial collection phases?", category: 'Implementation' },
          { question: "What are the core limitations of the technology stack you selected?", category: 'Technical' }
        ].map((item, idx) => ({
          ...item,
          panelist: selectedPanelists[idx % selectedPanelists.length]
        }));
        setQuestions(fallback);
      }
    };
    fetchQuestions();
  }, [project.abstractText, project.methodology, config]);

  useEffect(() => {
    let timer: any;
    if (phase === 'active' || phase === 'feedback') {
      timer = setInterval(() => {
        setTimeLeft((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [phase]);

  const handleSubmit = async () => {
    if (!response.trim()) return;
    const currentQuestion = questions[currentIndex];
    setPhase('evaluating');

    try {
      const evalRes = await evaluateResponse(currentQuestion.question, response, project.abstractText || '');
      setCurrentFeedback(evalRes);
      setSessionScores([...sessionScores, evalRes.score]);
      setHistory([
        ...history, 
        { 
          question: currentQuestion.question, 
          answer: response, 
          feedback: evalRes,
          category: currentQuestion.category 
        }
      ]);
      setPhase('feedback');
    } catch (e) {
      const fallbackFeedback: Feedback = {
        score: 75,
        semanticRelevance: 80,
        keywordAccuracy: 70,
        confidenceLevel: 75,
        strengths: ["Clear logic", "Good tech mention"],
        improvements: ["Be more specific about data"],
        betterExample: "A more robust response would include specific metrics from your methodology chapter."
      };
      setCurrentFeedback(fallbackFeedback);
      setSessionScores([...sessionScores, 75]);
      setHistory([
        ...history, 
        { 
          question: currentQuestion.question, 
          answer: response, 
          feedback: fallbackFeedback,
          category: currentQuestion.category 
        }
      ]);
      setPhase('feedback');
    }
  };

  const nextQuestion = () => {
    if (currentIndex + 1 < questions.length) {
      setCurrentIndex(currentIndex + 1);
      setResponse('');
      setPhase('active');
    } else {
      const avg = sessionScores.length > 0 ? sessionScores.reduce((a,b) => a+b, 0) / sessionScores.length : 0;
      onComplete({
        id: Math.random().toString(36).substr(2, 9),
        date: new Date().toLocaleDateString(),
        overallScore: Math.round(avg),
        duration: (config?.duration || 30) - Math.floor(timeLeft / 60),
        questionsAnswered: history.length,
        categoryScores: { Methodology: 75, Implementation: 80 },
        history: history
      });
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const activeQuestion = questions[currentIndex];
  const activePanelist = activeQuestion?.panelist || selectedPanelists[0];

  return (
    <div className="min-h-screen bg-slate-900 text-white flex flex-col">
      <header className="px-6 py-4 border-b border-white/10 flex items-center justify-between bg-slate-900 sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center font-black">IL</div>
          <div>
            <p className="font-black text-sm uppercase tracking-tight leading-none mb-1">Practice Session</p>
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">IntegrityLens AI Simulator</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden sm:flex items-center gap-3 px-5 py-2.5 bg-white/5 border border-white/10 rounded-2xl text-slate-300 font-mono shadow-inner">
            <Timer className="w-4 h-4 text-blue-400" />
            <span className="font-black text-lg">{formatTime(timeLeft)}</span>
          </div>
          <button onClick={onExit} className="px-4 py-2 hover:bg-red-500/10 text-slate-400 hover:text-red-400 rounded-xl transition-all text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
            <X className="w-4 h-4" /> Exit Session
          </button>
        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-4 sm:p-10">
        <div className="max-w-4xl w-full">
          {phase === 'intro' && (
            <div className="bg-white/5 border border-white/10 p-10 rounded-[40px] backdrop-blur-sm text-center relative overflow-hidden">
              <div className="absolute top-0 left-0 w-32 h-32 bg-blue-500/10 rounded-full blur-3xl" />
              <div className="w-20 h-20 bg-blue-600/20 text-blue-400 rounded-[28px] flex items-center justify-center mx-auto mb-8 shadow-inner">
                <MessageCircle className="w-10 h-10" />
              </div>
              <h2 className="text-3xl font-black mb-4 uppercase tracking-tighter italic">Virtual Panel Assembled</h2>

              <div className="bg-slate-800/50 p-8 rounded-[32px] text-left mb-10 border border-white/5">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-6">Simulation Panelists:</p>
                <div className="flex flex-wrap gap-4 mb-8">
                  {selectedPanelists.map((p) => (
                    <div key={p.id} className="flex items-center gap-3 px-4 py-2 bg-white/5 rounded-2xl border border-white/5">
                      <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-[10px] font-black">{p.name[0]}</div>
                      <div>
                        <p className="text-xs font-black uppercase tracking-tight">{p.name}</p>
                        <p className="text-[8px] text-slate-500 font-bold uppercase tracking-widest">{p.role}</p>
                      </div>
                    </div>
                  ))}
                </div>
                <p className="text-slate-300 leading-relaxed font-medium italic">
                  "The panel is ready to evaluate your research. We've prepared a sequence of challenging questions based on your abstract. Take a deep breath and defend your work with confidence."
                </p>
              </div>

              <button 
                onClick={() => setPhase('active')}
                className="px-16 py-6 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-3xl transition-all shadow-2xl shadow-blue-900/40 uppercase tracking-[0.2em] text-sm"
              >
                Enter Simulation
              </button>
            </div>
          )}

          {phase === 'active' && questions.length > 0 && (
            <div className="space-y-10 animate-in fade-in slide-in-from-bottom-6 duration-500">
              <div className="flex items-center justify-between">
                 <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-blue-600 text-white rounded-[24px] flex items-center justify-center text-xl font-black shadow-lg">
                      {activePanelist.name.split(' ')[1][0]}
                    </div>
                    <div>
                       <p className="text-[10px] font-black text-blue-400 uppercase tracking-[0.2em] mb-1">Asking Question {currentIndex + 1} of {questions.length}</p>
                       <h3 className="text-xl font-black italic uppercase tracking-tighter leading-none">{activePanelist.name}</h3>
                       <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">{activePanelist.role}</p>
                    </div>
                 </div>
                 <div className="px-4 py-2 bg-white/5 rounded-full border border-white/5 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                    Track: {questions[currentIndex].category}
                 </div>
              </div>

              <div className="bg-slate-800/80 border border-white/10 p-12 rounded-[50px] shadow-2xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-12 opacity-5 group-hover:opacity-10 transition-opacity"><MessageCircle className="w-24 h-24" /></div>
                <p className="text-2xl md:text-3xl font-bold text-slate-100 leading-snug italic">
                  "{questions[currentIndex].question}"
                </p>
              </div>

              <div className="space-y-6">
                <div className="flex items-center justify-between">
                  <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Defense Response Area</h3>
                  <span className={`text-[10px] font-bold tracking-widest ${response.length > 900 ? 'text-amber-500' : 'text-slate-600'}`}>{response.length} / 1000 CHARACTERS</span>
                </div>
                <div className="relative">
                  <textarea 
                    autoFocus
                    className="w-full min-h-[250px] bg-slate-800/50 border border-white/10 rounded-[40px] p-10 focus:ring-2 focus:ring-blue-500 outline-none text-slate-100 placeholder:text-slate-600 resize-none transition-all font-medium leading-relaxed shadow-inner"
                    placeholder="Provide a clear, structured explanation of your research choices..."
                    value={response}
                    onChange={(e) => setResponse(e.target.value)}
                  />
                  <div className="absolute right-8 bottom-8">
                    <button className="p-5 bg-blue-600 text-white hover:bg-blue-500 rounded-[24px] transition-all shadow-xl shadow-blue-900/40 group">
                      <Mic className="w-6 h-6 group-hover:scale-110 transition-transform" />
                    </button>
                  </div>
                </div>

                <div className="flex gap-4 pt-4">
                  <button className="px-10 py-5 bg-white/5 hover:bg-white/10 text-slate-500 font-black rounded-3xl transition-all uppercase tracking-widest text-[10px]">
                    Skip for now
                  </button>
                  <button 
                    disabled={!response || response.length < 10}
                    onClick={handleSubmit}
                    className="flex-grow py-5 bg-blue-600 hover:bg-blue-500 disabled:opacity-20 disabled:cursor-not-allowed text-white font-black rounded-3xl transition-all flex items-center justify-center gap-3 shadow-2xl shadow-blue-900/40 uppercase tracking-widest text-xs"
                  >
                    Confirm Answer <Send className="w-4 h-4" />
                  </button>
                </div>
              </div>
            </div>
          )}

          {phase === 'evaluating' && (
            <div className="text-center py-20 animate-in fade-in duration-700">
              <div className="relative w-32 h-32 mx-auto mb-10">
                <Loader2 className="w-full h-full text-blue-500 animate-spin absolute inset-0 opacity-20" />
                <div className="absolute inset-0 flex items-center justify-center animate-pulse">
                  <Sparkles className="w-12 h-12 text-blue-400" />
                </div>
              </div>
              <h2 className="text-4xl font-black mb-4 uppercase tracking-tighter italic">Generating Critique</h2>
              <p className="text-slate-500 mb-12 font-medium tracking-wide">Panelists are reviewing semantic relevance and institutional accuracy.</p>

              <div className="max-w-md mx-auto grid grid-cols-1 gap-4">
                 {[
                   { label: 'Analyzing Context', color: 'text-green-500' },
                   { label: 'Checking Key Phrases', color: 'text-blue-500' },
                   { label: 'Scoring Delivery', color: 'text-purple-500' }
                 ].map((item, idx) => (
                    <div key={idx} className="flex items-center gap-4 p-6 bg-white/5 rounded-3xl border border-white/5 animate-in slide-in-from-bottom-2" style={{ animationDelay: `${idx * 200}ms` }}>
                       <div className={`w-2 h-2 rounded-full bg-current ${item.color} animate-pulse`} />
                       <span className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em]">{item.label}</span>
                    </div>
                 ))}
              </div>
            </div>
          )}

          {phase === 'feedback' && currentFeedback && (
            <div className="space-y-10 animate-in zoom-in-95 duration-500">
              <header className="flex flex-col sm:flex-row sm:items-end justify-between gap-6 border-b border-white/5 pb-8">
                <div>
                  <div className="flex items-center gap-3 mb-4">
                     <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-[10px] font-black uppercase">Critique</div>
                     <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Institutional Evaluation</span>
                  </div>
                  <h2 className="text-5xl font-black italic uppercase tracking-tighter leading-none">Panel <span className="text-blue-500">Response</span></h2>
                </div>
                <div className="bg-slate-800 p-8 rounded-[40px] flex items-center gap-8 border border-white/10 shadow-2xl relative overflow-hidden group">
                  <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity"><CheckCircle2 className="w-20 h-20" /></div>
                  <div className="text-right">
                    <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-2">Defense Score</p>
                    <p className="text-6xl font-black text-blue-400 leading-none tracking-tighter">{currentFeedback.score}<span className="text-xl text-slate-600">/100</span></p>
                  </div>
                </div>
              </header>

              <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
                <div className="lg:col-span-2 space-y-10">
                  <div className="bg-slate-800/40 border border-white/10 rounded-[50px] p-12 shadow-xl relative">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                      <div className="space-y-8">
                        <h4 className="text-green-400 font-black flex items-center gap-3 uppercase tracking-[0.2em] text-[10px]">
                          <CheckCircle2 className="w-4 h-4" /> Strong Indicators
                        </h4>
                        <ul className="space-y-5">
                          {currentFeedback.strengths.map((s, i) => (
                            <li key={i} className="text-slate-300 text-sm font-medium leading-relaxed flex gap-4">
                              <span className="w-6 h-6 bg-green-500/10 text-green-500 rounded-full flex items-center justify-center text-[10px] font-black shrink-0">+</span>
                              {s}
                            </li>
                          ))}
                        </ul>
                      </div>
                      <div className="space-y-8">
                        <h4 className="text-amber-400 font-black flex items-center gap-3 uppercase tracking-[0.2em] text-[10px]">
                          <AlertCircle className="w-4 h-4" /> Areas for Growth
                        </h4>
                        <ul className="space-y-5">
                          {currentFeedback.improvements.map((s, i) => (
                            <li key={i} className="text-slate-300 text-sm font-medium leading-relaxed flex gap-4">
                              <span className="w-6 h-6 bg-amber-500/10 text-amber-500 rounded-full flex items-center justify-center text-[10px] font-black shrink-0">!</span>
                              {s}
                            </li>
                          ))}
                        </ul>
                      </div>
                    </div>
                  </div>

                  <div className="bg-gradient-to-br from-blue-600/10 to-indigo-600/10 border border-blue-500/20 rounded-[40px] p-10 relative group">
                    <div className="absolute top-0 right-0 p-10 opacity-5 group-hover:opacity-20 transition-all"><Sparkles className="w-12 h-12" /></div>
                    <h4 className="text-blue-400 font-black mb-6 uppercase tracking-[0.2em] text-[10px] flex items-center gap-2">
                       <Sparkles className="w-4 h-4" /> AI Model Response
                    </h4>
                    <p className="text-slate-100 text-lg italic font-medium leading-relaxed">
                      "{currentFeedback.betterExample}"
                    </p>
                  </div>
                </div>

                <div className="space-y-8">
                  <div className="bg-slate-800 border border-white/5 rounded-[40px] p-10 space-y-10 shadow-2xl relative overflow-hidden">
                    <div className="absolute bottom-0 right-0 p-8 opacity-5"><BarChart className="w-20 h-20" /></div>
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Diagnostic Metrics</h4>
                    <div className="space-y-10">
                      {[
                        { label: 'Relevance', val: currentFeedback.semanticRelevance, color: 'bg-blue-500' },
                        { label: 'Keyword Match', val: currentFeedback.keywordAccuracy, color: 'bg-emerald-500' },
                        { label: 'Confidence', val: currentFeedback.confidenceLevel, color: 'bg-purple-500' }
                      ].map((m, i) => (
                        <div key={i}>
                          <div className="flex justify-between text-[10px] font-black uppercase mb-3 tracking-widest">
                            <span className="text-slate-400">{m.label}</span>
                            <span className="text-white">{m.val}%</span>
                          </div>
                          <div className="h-2 bg-white/5 rounded-full overflow-hidden border border-white/5">
                            <div className={`h-full ${m.color} shadow-[0_0_15px_rgba(255,255,255,0.1)] transition-all duration-1000`} style={{ width: `${m.val}%` }} />
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  <button 
                    onClick={nextQuestion}
                    className="w-full py-8 bg-white text-slate-900 font-black rounded-[32px] hover:bg-blue-50 transition-all flex items-center justify-center gap-4 shadow-2xl uppercase tracking-[0.2em] text-xs group"
                  >
                    Proceed Sequence <ChevronRight className="w-5 h-5 group-hover:translate-x-2 transition-transform" />
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default PracticeSessionView;

import React, { useState } from 'react';
import LandingView from './views/Landing/LandingView';
import LoginView from './views/Auth/LoginView';
import RegisterView from './views/Auth/RegisterView';
import VerificationView from './views/Auth/VerificationView';
import DashboardView from './views/Dashboard/DashboardView';
import FacultyDashboardView from './views/Dashboard/FacultyDashboardView';
import AdminDashboardView from './views/Dashboard/AdminDashboardView';
import ProjectSetupView from './views/Project/ProjectSetupView';
import AbstractUploadView from './views/Project/AbstractUploadView';
import SessionConfigView from './views/Session/SessionConfigView';
import PracticeSessionView from './views/Session/PracticeSessionView';
import SessionSummaryView from './views/Session/SessionSummaryView';
import ReadinessDashboardView from './views/Dashboard/ReadinessDashboardView';
import { ProjectProfile, SessionResult, User, UserRole } from './types';

enum ViewState {
  LANDING,
  LOGIN,
  REGISTER,
  VERIFICATION_PENDING,
  EMAIL_VERIFIED,
  STUDENT_DASHBOARD,
  FACULTY_DASHBOARD,
  ADMIN_DASHBOARD,
  PROJECT_SETUP,
  ABSTRACT_UPLOAD,
  SESSION_CONFIG,
  PRACTICE_SESSION,
  SESSION_SUMMARY,
  READINESS_DASHBOARD
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.LANDING);
  const [user, setUser] = useState<User | null>(null);
  const [project, setProject] = useState<ProjectProfile | null>(null);
  const [lastSession, setLastSession] = useState<SessionResult | null>(null);
  const [sessionConfig, setSessionConfig] = useState<any>(null);

  const handleLogin = (email: string, role: UserRole) => {
    const demoUser: User = { 
      name: role === UserRole.STUDENT ? 'Juan Dela Cruz' : role === UserRole.FACULTY ? 'Dr. Sarah Santos' : 'System Admin', 
      email: email, 
      role: role,
      program: 'BSIT',
      yearLevel: '4th Year'
    };
    setUser(demoUser);

    if (role === UserRole.STUDENT) setCurrentView(ViewState.STUDENT_DASHBOARD);
    else if (role === UserRole.FACULTY) setCurrentView(ViewState.FACULTY_DASHBOARD);
    else setCurrentView(ViewState.ADMIN_DASHBOARD);
  };

  const handleRegister = (data: any) => {
    setUser({ name: data.fullName, email: data.email, role: UserRole.STUDENT });
    setCurrentView(ViewState.VERIFICATION_PENDING);
  };

  const logout = () => {
    setUser(null);
    setCurrentView(ViewState.LANDING);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 overflow-x-hidden">
      {currentView === ViewState.LANDING && (
        <LandingView 
          onGetStarted={() => setCurrentView(ViewState.REGISTER)} 
          onLogin={() => setCurrentView(ViewState.LOGIN)} 
        />
      )}

      {currentView === ViewState.LOGIN && (
        <LoginView onLogin={handleLogin} onGoToRegister={() => setCurrentView(ViewState.REGISTER)} />
      )}

      {currentView === ViewState.REGISTER && (
        <RegisterView onRegister={handleRegister} onGoToLogin={() => setCurrentView(ViewState.LOGIN)} />
      )}

      {currentView === ViewState.VERIFICATION_PENDING && (
        <VerificationView 
          status="pending" 
          email={user?.email || ''} 
          onVerify={() => setCurrentView(ViewState.EMAIL_VERIFIED)} 
        />
      )}

      {currentView === ViewState.EMAIL_VERIFIED && (
        <VerificationView 
          status="verified" 
          onGoToLogin={() => setCurrentView(ViewState.LOGIN)} 
        />
      )}

      {currentView === ViewState.STUDENT_DASHBOARD && (
        <DashboardView 
          user={user} 
          project={project}
          onStartProject={() => setCurrentView(ViewState.PROJECT_SETUP)}
          onStartPractice={() => setCurrentView(ViewState.SESSION_CONFIG)}
          onViewAnalytics={() => setCurrentView(ViewState.READINESS_DASHBOARD)}
          onLogout={logout}
        />
      )}

      {currentView === ViewState.FACULTY_DASHBOARD && (
        <FacultyDashboardView user={user!} onLogout={logout} />
      )}

      {currentView === ViewState.ADMIN_DASHBOARD && (
        <AdminDashboardView user={user!} onLogout={logout} />
      )}

      {currentView === ViewState.PROJECT_SETUP && (
        <ProjectSetupView 
          onSave={(p) => { setProject(p); setCurrentView(ViewState.ABSTRACT_UPLOAD); }} 
          onCancel={() => setCurrentView(ViewState.STUDENT_DASHBOARD)}
        />
      )}

      {currentView === ViewState.ABSTRACT_UPLOAD && (
        <AbstractUploadView 
          project={project!} 
          onComplete={(p) => { setProject(p); setCurrentView(ViewState.STUDENT_DASHBOARD); }} 
        />
      )}

      {currentView === ViewState.SESSION_CONFIG && (
        <SessionConfigView 
          onStart={(config) => { setSessionConfig(config); setCurrentView(ViewState.PRACTICE_SESSION); }}
          onBack={() => setCurrentView(ViewState.STUDENT_DASHBOARD)}
        />
      )}

      {currentView === ViewState.PRACTICE_SESSION && (
        <PracticeSessionView 
          project={project!}
          config={sessionConfig}
          onComplete={(result) => { setLastSession(result); setCurrentView(ViewState.SESSION_SUMMARY); }}
          onExit={() => setCurrentView(ViewState.STUDENT_DASHBOARD)}
        />
      )}

      {currentView === ViewState.SESSION_SUMMARY && (
        <SessionSummaryView 
          result={lastSession!} 
          onGoDashboard={() => setCurrentView(ViewState.STUDENT_DASHBOARD)}
          onViewDetailed={() => setCurrentView(ViewState.READINESS_DASHBOARD)}
        />
      )}

      {currentView === ViewState.READINESS_DASHBOARD && (
        <ReadinessDashboardView 
          onBack={() => setCurrentView(ViewState.STUDENT_DASHBOARD)} 
          onNewSession={() => setCurrentView(ViewState.SESSION_CONFIG)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  X, Mic, Send, Loader2, Sparkles, 
  MessageCircle, Timer, ChevronRight, CheckCircle2,
  AlertCircle, UserCircle, BarChart
} from 'lucide-react';
import { ProjectProfile, Feedback, SessionResult, QuestionAnswer, Panelist } from '../../types';
import { PANELISTS } from '../../constants';
import { generateQuestions, evaluateResponse } from '../../services/geminiService';

interface Props {
  project: ProjectProfile;
  config?: any;
  onComplete: (result: SessionResult) => void;
  onExit: () => void;
}

const PracticeSessionView: React.FC<Props> = ({ project, config, onComplete, onExit }) => {
  const [phase, setPhase] = useState<'intro' | 'active' | 'evaluating' | 'feedback'>('intro');
  const [questions, setQuestions] = useState<any[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState((config?.duration || 30) * 60);
  const [response, setResponse] = useState('');
  const [currentFeedback, setCurrentFeedback] = useState<Feedback | null>(null);
  const [history, setHistory] = useState<QuestionAnswer[]>([]);
  const [sessionScores, setSessionScores] = useState<number[]>([]);

  // Resolve panelist objects from IDs
  const selectedPanelists = PANELISTS.filter(p => config?.selectedPanelistIds?.includes(p.id)) || [PANELISTS[1]];

  useEffect(() => {
    const fetchQuestions = async () => {
      try {
        // We use the first panelist to drive the question generation logic for now
        const q = await generateQuestions(
          project.abstractText || '', 
          selectedPanelists[0], 
          config?.difficulty || 'Intermediate', 
          config?.focusAreas || ['Methodology']
        );

        // Randomly assign a panelist from the selected list to each question
        const assignedQuestions = q.map((item: any) => ({
          ...item,
          panelist: selectedPanelists[Math.floor(Math.random() * selectedPanelists.length)]
        }));

        setQuestions(assignedQuestions);
      } catch (e) {
        const fallback = [
          { question: `Can you explain why you chose a ${project.methodology} research methodology over other approaches for this project?`, category: 'Methodology' },
          { question: "How does your system handle potential data noise during initial collection phases?", category: 'Implementation' },
          { question: "What are the core limitations of the technology stack you selected?", category: 'Technical' }
        ].map((item, idx) => ({
          ...item,
          panelist: selectedPanelists[idx % selectedPanelists.length]
        }));
        setQuestions(fallback);
      }
    };
    fetchQuestions();
  }, [project.abstractText, project.methodology, config]);

  useEffect(() => {
    let timer: any;
    if (phase === 'active' || phase === 'feedback') {
      timer = setInterval(() => {
        setTimeLeft((prev) => (prev > 0 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [phase]);

  const handleSubmit = async () => {
    if (!response.trim()) return;
    const currentQuestion = questions[currentIndex];
    setPhase('evaluating');

    try {
      const evalRes = await evaluateResponse(currentQuestion.question, response, project.abstractText || '');
      setCurrentFeedback(evalRes);
      setSessionScores([...sessionScores, evalRes.score]);
      setHistory([
        ...history, 
        { 
          question: currentQuestion.question, 
          answer: response, 
          feedback: evalRes,
          category: currentQuestion.category 
        }
      ]);
      setPhase('feedback');
    } catch (e) {
      const fallbackFeedback: Feedback = {
        score: 75,
        semanticRelevance: 80,
        keywordAccuracy: 70,
        confidenceLevel: 75,
        strengths: ["Clear logic", "Good tech mention"],
        improvements: ["Be more specific about data"],
        betterExample: "A more robust response would include specific metrics from your methodology chapter."
      };
      setCurrentFeedback(fallbackFeedback);
      setSessionScores([...sessionScores, 75]);
      setHistory([
        ...history, 
        { 
          question: currentQuestion.question, 
          answer: response, 
          feedback: fallbackFeedback,
          category: currentQuestion.category 
        }
      ]);
      setPhase('feedback');
    }
  };

  const nextQuestion = () => {
    if (currentIndex + 1 < questions.length) {
      setCurrentIndex(currentIndex + 1);
      setResponse('');
      setPhase('active');
    } else {
      const avg = sessionScores.length > 0 ? sessionScores.reduce((a,b) => a+b, 0) / sessionScores.length : 0;
      onComplete({
        id: Math.random().toString(36).substr(2, 9),
        date: new Date().toLocaleDateString(),
        overallScore: Math.round(avg),
        duration: (config?.duration || 30) - Math.floor(timeLeft / 60),
        questionsAnswered: history.length,
        categoryScores: { Methodology: 75, Implementation: 80 },
        history: history
      });
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const activeQuestion = questions[currentIndex];
  const activePanelist = activeQuestion?.panelist || selectedPanelists[0];

  return (
    <div className="min-h-screen bg-slate-900 text-white flex flex-col">
      <header className="px-6 py-4 border-b border-white/10 flex items-center justify-between bg-slate-900 sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center font-black">IL</div>
          <div>
            <p className="font-black text-sm uppercase tracking-tight leading-none mb-1">Practice Session</p>
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">IntegrityLens AI Simulator</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden sm:flex items-center gap-3 px-5 py-2.5 bg-white/5 border border-white/10 rounded-2xl text-slate-300 font-mono shadow-inner">
            <Timer className="w-4 h-4 text-blue-400" />
            <span className="font-black text-lg">{formatTime(timeLeft)}</span>
          </div>
          <button onClick={onExit} className="px-4 py-2 hover:bg-red-500/10 text-slate-400 hover:text-red-400 rounded-xl transition-all text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
            <X className="w-4 h-4" /> Exit Session
          </button>
        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-4 sm:p-10">
        <div className="max-w-4xl w-full">
          {phase === 'intro' && (
            <div className="bg-white/5 border border-white/10 p-10 rounded-[40px] backdrop-blur-sm text-center relative overflow-hidden">
              <div className="absolute top-0 left-0 w-32 h-32 bg-blue-500/10 rounded-full blur-3xl" />
              <div className="w-20 h-20 bg-blue-600/20 text-blue-400 rounded-[28px] flex items-center justify-center mx-auto mb-8 shadow-inner">
                <MessageCircle className="w-10 h-10" />
              </div>
              <h2 className="text-3xl font-black mb-4 uppercase tracking-tighter italic">Virtual Panel Assembled</h2>

              <div className="bg-slate-800/50 p-8 rounded-[32px] text-left mb-10 border border-white/5">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-6">Simulation Panelists:</p>
                <div className="flex flex-wrap gap-4 mb-8">
                  {selectedPanelists.map((p) => (
                    <div key={p.id} className="flex items-center gap-3 px-4 py-2 bg-white/5 rounded-2xl border border-white/5">
                      <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-[10px] font-black">{p.name[0]}</div>
                      <div>
                        <p className="text-xs font-black uppercase tracking-tight">{p.name}</p>
                        <p className="text-[8px] text-slate-500 font-bold uppercase tracking-widest">{p.role}</p>
                      </div>
                    </div>
                  ))}
                </div>
                <p className="text-slate-300 leading-relaxed font-medium italic">
                  "The panel is ready to evaluate your research. We've prepared a sequence of challenging questions based on your abstract. Take a deep breath and defend your work with confidence."
                </p>
              </div>

              <button 
                onClick={() => setPhase('active')}
                className="px-16 py-6 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-3xl transition-all shadow-2xl shadow-blue-900/40 uppercase tracking-[0.2em] text-sm"
              >
                Enter Simulation
              </button>
            </div>
          )}

          {phase === 'active' && questions.length > 0 && (
            <div className="space-y-10 animate-in fade-in slide-in-from-bottom-6 duration-500">
              <div className="flex items-center justify-between">
                 <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-blue-600 text-white rounded-[24px] flex items-center justify-center text-xl font-black shadow-lg">
                      {activePanelist.name.split(' ')[1][0]}
                    </div>
                    <div>
                       <p className="text-[10px] font-black text-blue-400 uppercase tracking-[0.2em] mb-1">Asking Question {currentIndex + 1} of {questions.length}</p>
                       <h3 className="text-xl font-black italic uppercase tracking-tighter leading-none">{activePanelist.name}</h3>
                       <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">{activePanelist.role}</p>
                    </div>
                 </div>
                 <div className="px-4 py-2 bg-white/5 rounded-full border border-white/5 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                    Track: {questions[currentIndex].category}
                 </div>
              </div>

              <div className="bg-slate-800/80 border border-white/10 p-12 rounded-[50px] shadow-2xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-12 opacity-5 group-hover:opacity-10 transition-opacity"><MessageCircle className="w-24 h-24" /></div>
                <p className="text-2xl md:text-3xl font-bold text-slate-100 leading-snug italic">
                  "{questions[currentIndex].question}"
                </p>
              </div>

              <div className="space-y-6">
                <div className="flex items-center justify-between">
                  <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Defense Response Area</h3>
                  <span className={`text-[10px] font-bold tracking-widest ${response.length > 900 ? 'text-amber-500' : 'text-slate-600'}`}>{response.length} / 1000 CHARACTERS</span>
                </div>
                <div className="relative">
                  <textarea 
                    autoFocus
