      setCurrentIndex(currentIndex + 1);
      setResponse('');
      setPhase('active');
      setCurrentFeedback(null);
    } else {
      finalizeSession(newHistory);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

