                  <div className="bg-slate-800 border border-white/5 rounded-[40px] p-10 space-y-10 shadow-2xl relative overflow-hidden">
                    <div className="absolute bottom-0 right-0 p-8 opacity-5"><BarChart className="w-20 h-20" /></div>
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Diagnostic Metrics</h4>
                    <div className="space-y-10">
                      {[
                        { label: 'Relevance', val: currentFeedback.semanticRelevance, color: 'bg-blue-500' },
                        { label: 'Keyword Match', val: currentFeedback.keywordAccuracy, color: 'bg-emerald-500' },
                        { label: 'Confidence', val: currentFeedback.confidenceLevel, color: 'bg-purple-500' }
                      ].map((m, i) => (
                        <div key={i}>
                          <div className="flex justify-between text-[10px] font-black uppercase mb-3 tracking-widest">
                            <span className="text-slate-400">{m.label}</span>
